class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        if n == 1:
            return 0

        changes = 0

        # Function to choose a non almost-equal neighbor for the current character
        def choose_different_char(c1, c2):
            """Finds a character different from c1 and its almost-equal neighbor c2."""
            for c in "abcdefghijklmnopqrstuvwxyz":
                if c != c1 and c != c2 and (abs(ord(c) - ord(c1)) > 1 or abs(ord(c) - ord(c1)) == 0):
                    return c
            return c1

        # We proceed by checking every pair of adjacent characters
        chars = list(word)

        for i in range(n - 1):
            if chars[i] == chars[i + 1] or abs(ord(chars[i]) - ord(chars[i + 1])) == 1:
                # Need to change the next character to something that is not almost-equal
                replacement = choose_different_char(chars[i], None if i + 2 >= n else chars[i + 2])
                chars[i + 1] = replacement
                changes += 1

        return changes
